export function wallParts(c){const out=[];for(const w of c.walls){const len=Math.hypot(w.b[0]-w.a[0],w.b[1]-w.a[1]);const t=w.thickness??(w.external?c.settings.externalWallThickness:c.settings.wallThickness);const push=(s,e,y,h,solid=true,kind='wall')=>{if(e<=s||h<=0)return;const x=w.a[0]+(w.b[0]-w.a[0])*(s+e)/2/len,z=w.a[1]+(w.b[1]-w.a[1])*(s+e)/2/len;out.push({x,z,width:w.a[1]===w.b[1]?e-s:t,depth:w.a[0]===w.b[0]?e-s:t,y,h,solid,kind});};let last=0;for(const o of [...w.openings].sort((a,b)=>a.start-b.start)){push(last,o.start,0,c.settings.ceilingHeight);let sill=o.sill??c.settings.windowSill,oh=o.height??(o.type==='window'?c.settings.windowHeight:c.settings.doorHeight);if(o.type==='window'){push(o.start,o.start+o.width,0,sill);push(o.start,o.start+o.width,sill,oh,true,'glass');push(o.start,o.start+o.width,sill+oh,c.settings.ceilingHeight-sill-oh);}else{push(o.start,o.start+o.width,oh,c.settings.ceilingHeight-oh,false);if(o.type==='entry'||o.open===false)push(o.start,o.start+o.width,0,oh,true,'door');}last=o.start+o.width;}push(last,len,0,c.settings.ceilingHeight);}return out;}
export function overlaps(a,b,pad=0){return Math.abs(a.x-b.x)<(a.width+b.width)/2+pad&&Math.abs(a.z-b.z)<(a.depth+b.depth)/2+pad;}
export function itemBox(f){const a=f.rotation*Math.PI/180;return {x:f.position[0],z:f.position[1],width:Math.abs(Math.cos(a))*f.size[0]+Math.abs(Math.sin(a))*f.size[2],depth:Math.abs(Math.sin(a))*f.size[0]+Math.abs(Math.cos(a))*f.size[2]};}
export function inside(c,x,z,r=0){return c.rooms.some(({rect:b})=>x-r>=b[0]&&x+r<=b[2]&&z-r>=b[1]&&z+r<=b[3]);}
export function playerBlocked(c,parts,items,x,z){const b=c.bounds,r=c.settings.playerRadius;if(x-r<b[0]||x+r>b[2]||z-r<b[1]||z+r>b[3]||![[x-r,z],[x+r,z],[x,z-r],[x,z+r]].every(([a,b])=>inside(c,a,b)))return true;return [...parts.filter(p=>p.solid),...items.map(itemBox)].some(p=>{const dx=Math.max(Math.abs(x-p.x)-p.width/2,0),dz=Math.max(Math.abs(z-p.z)-p.depth/2,0);return dx*dx+dz*dz<r*r;});}
export function validPlacement(c,parts,items,f){const b=itemBox(f);const corners=[[-1,-1],[-1,1],[1,-1],[1,1]];return f.size[1]<c.settings.ceilingHeight&&corners.every(([i,j])=>inside(c,b.x+i*b.width/2,b.z+j*b.depth/2))&&!parts.some(p=>p.solid&&overlaps(b,p,5))&&!items.some(g=>g.id!==f.id&&overlaps(b,itemBox(g),5));}
export function validateModel(m){const fail=()=>{throw Error('모델 JSON 형식 또는 치수가 올바르지 않습니다.');};const nums=(a,n)=>Array.isArray(a)&&a.length===n&&a.every(v=>Number.isFinite(v)&&Math.abs(v)<100000);if(!m||m.schemaVersion!==1||m.config?.units!=='mm'||m.furniture?.units!=='mm')fail();const c=m.config,s=c.settings;if(!s||!nums(c.bounds,4)||!nums(c.spawn,2)||!Array.isArray(c.rooms)||!c.rooms.length||c.rooms.length>100||!Array.isArray(c.walls)||c.walls.length>200||!Array.isArray(c.extensions)||!Array.isArray(m.furniture.items)||m.furniture.items.length>300||!Array.isArray(m.furniture.catalog))fail();for(const k of ['ceilingHeight','eyeHeight','playerRadius','speed','wallThickness','externalWallThickness','doorHeight','windowSill','windowHeight','snap'])if(!Number.isFinite(s[k])||s[k]<=0||s[k]>10000)fail();if(s.eyeHeight>=s.ceilingHeight||s.doorHeight>s.ceilingHeight||s.windowSill+s.windowHeight>s.ceilingHeight)fail();for(const r of [...c.rooms,...c.extensions])if(!nums(r.rect,4)||r.rect[2]<=r.rect[0]||r.rect[3]<=r.rect[1]||typeof r.name!=='string')fail();for(const w of c.walls){if(!nums(w.a,2)||!nums(w.b,2)||(w.a[0]!==w.b[0]&&w.a[1]!==w.b[1])||!Array.isArray(w.openings))fail();let last=0,len=Math.hypot(w.b[0]-w.a[0],w.b[1]-w.a[1]);if(!len)fail();for(const o of [...w.openings].sort((a,b)=>a.start-b.start)){if(!['window','door','entry'].includes(o.type)||!Number.isFinite(o.start)||!Number.isFinite(o.width)||o.width<=0||o.start<last||o.start+o.width>len)fail();last=o.start+o.width;}}
const ids=new Set();for(const f of m.furniture.items){if(typeof f.id!=='string'||ids.has(f.id)||typeof f.name!=='string'||!nums(f.position,2)||!nums(f.size,3)||f.size.some(n=>n<50)||!Number.isFinite(f.rotation))fail();ids.add(f.id);}for(const f of m.furniture.catalog)if(!nums(f.size,3)||typeof f.name!=='string')fail();return m;}
